BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L2 — Section 501(h) expenditure election safe harbor
(3, 'Tax-Exempt Organizations', 'Hope Health Alliance, a 501(c)(3) public charity, wants clear dollar limits on how much it can spend on lobbying activities. Its attorney recommends making an election with the IRS. Which election provides specific expenditure thresholds as a safe harbor for lobbying?', '["The Section 501(h) expenditure election", "The Section 509(a)(1) public support election", "The Section 4940 net investment income election", "The Section 527 political organization election"]'::jsonb, 0, 'Under IRC Section 501(h), eligible 501(c)(3) public charities may elect to use specific dollar thresholds rather than the vague "substantial part" test for lobbying. This election provides a safe harbor with graduated limits based on exempt purpose expenditures. Section 509(a)(1) relates to public charity classification based on public support, not lobbying dollar limits.', 'easy', 2),

-- Q2: medium / L3 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Coastal Regional Hospital, a 501(c)(3), operates a cafeteria that serves meals to patients, their families, staff, and walk-in visitors from the neighborhood. The cafeteria generates $200,000 annually, with 60% from patients, families, and employees and 40% from walk-in visitors. Apply the UBIT three-part test and convenience exclusion to determine the likely treatment.', '["All $200,000 is subject to UBIT because the cafeteria is a trade or business regularly carried on", "The cafeteria likely qualifies for the convenience exclusion under Section 513(a)(2) because it primarily serves patients, families, and employees", "Only the $80,000 from walk-in visitors is subject to UBIT under a proportional allocation", "All $200,000 is excluded because hospitals are automatically exempt from UBIT on all activities"]'::jsonb, 1, 'Under IRC Section 513(a)(2), income from a trade or business carried on primarily for the convenience of members, students, patients, officers, or employees is excluded from UBIT. Since 60% of revenue comes from patients, families, and staff, the cafeteria primarily serves the convenience population. Option C incorrectly splits revenue proportionally; the convenience exclusion applies to the activity as a whole, not on a pro-rata basis.', 'medium', 3),

-- Q3: medium / L2 — One-third support test for public charity under Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Riverdale Education Fund, a 501(c)(3), receives the following support over a four-year period: $400,000 from government grants, $200,000 from individual donors, and $600,000 from a single wealthy benefactor. Under Section 509(a)(1), which factor is most relevant to determining whether the organization qualifies as a public charity?', '["Whether the organization spends at least 85% of funds on charitable programs", "Whether the single benefactor is a disqualified person under Section 4946", "Whether the organization receives at least one-third of total support from the general public or government sources", "Whether the organization has applied for the Section 501(h) expenditure election"]'::jsonb, 2, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it normally receives at least one-third of its total support from government sources and the general public. Here, the $400,000 government support and $200,000 from public donors total $600,000 out of $1,200,000 (50%), meeting the test. Option B confuses private foundation self-dealing rules with the public support classification test.', 'medium', 2),

-- Q4: hard / L4 — Controlled entity payments and UBIT under Section 512(b)(13)
(3, 'Tax-Exempt Organizations', 'Bright Horizons Foundation, a 501(c)(3), owns 90% of a for-profit subsidiary, Horizon Solutions LLC. The subsidiary pays $150,000 in annual rent to the foundation for office space with a fair market rental value of $100,000. The foundation''s controller argues that rent from real property is always excluded from UBIT under Section 512(b)(3). Evaluate whether the controlled entity modification applies and how the excess rent is treated.', '["All $150,000 is excluded from UBIT because real property rent is passive income", "All $150,000 is subject to UBIT because the foundation owns more than 50% of the subsidiary", "Only $100,000 is subject to UBIT and the $50,000 excess is excluded as a penalty premium", "The $50,000 excess above fair market value is included in UBIT under the controlled entity rules of Section 512(b)(13)"]'::jsonb, 3, 'Under IRC Section 512(b)(13), when a tax-exempt organization controls an entity (owning more than 50% by vote or value), rents, interest, or royalties paid by the controlled entity are included in UBIT to the extent they exceed fair market value. The $50,000 excess ($150,000 minus $100,000 FMV) is subject to UBIT. Option A incorrectly ignores the controlled entity modification that overrides the general real property rent exclusion.', 'hard', 4),

-- Q5: hard / L4 — Section 4943 excess business holdings with disqualified persons aggregation
(3, 'Tax-Exempt Organizations', 'The Palmer Family Foundation, a private foundation, owns 12% of the voting stock of Palmer Industries. The founder''s adult children collectively own 15%. The foundation''s investment advisor proposes purchasing an additional 5% stake, arguing the foundation''s individual holding would remain below 20%. Evaluate whether the proposed acquisition complies with Section 4943.', '["The acquisition violates Section 4943 because the foundation plus disqualified persons would hold 32%, exceeding the 20% combined limit, creating 12% excess holdings", "The acquisition is permissible because the foundation''s direct holding of 17% remains below the 20% threshold", "The acquisition is permissible because only foundation-owned shares count toward the excess business holdings limit", "The acquisition violates Section 4943 only if the children are classified as substantial contributors"]'::jsonb, 0, 'Under IRC Section 4943, the combined holdings of a private foundation and its disqualified persons cannot exceed 20% of voting stock. Disqualified persons include the founder''s family members. Currently the combined holding is 27% (12% + 15%); the proposed purchase would increase it to 32%, creating 12% in excess holdings. Option B incorrectly considers only the foundation''s direct share, ignoring the mandatory aggregation of disqualified persons'' holdings.', 'hard', 4),

-- Q6: hard / L4 — Private inurement vs private benefit doctrine
(3, 'Tax-Exempt Organizations', 'Lakewood Community Services, a 501(c)(3), pays its founder-CEO a salary of $600,000, exceeding comparable compensation by $250,000. It also awards a $50,000 research grant to an unrelated professor without competitive selection or oversight. Evaluate how each arrangement is treated under the private inurement prohibition and the private benefit doctrine, and which penalty regime applies.', '["Both arrangements trigger private inurement and intermediate sanctions under Section 4958", "Both constitute private benefit, but neither triggers intermediate sanctions because no self-dealing is involved", "The excess CEO compensation constitutes private inurement subject to Section 4958 intermediate sanctions, while the research grant constitutes impermissible private benefit but is not subject to Section 4958 because the professor is not a disqualified person", "The CEO salary triggers only the private benefit doctrine because $600,000 alone does not meet the inurement threshold"]'::jsonb, 2, 'Under IRC Section 501(c)(3), private inurement applies to transactions with insiders (officers, directors, key employees), while private benefit is broader, covering benefits to any private individual. The CEO''s excess compensation triggers private inurement and Section 4958 intermediate sanctions on the disqualified person. The unrelated professor is not a disqualified person, so the grant represents private benefit outside Section 4958. Option A incorrectly applies intermediate sanctions to both arrangements.', 'hard', 4),

-- Q7: medium / L2 — Form 990-PF and Form 990-T dual filing for private foundations
(3, 'Tax-Exempt Organizations', 'Redwood Heritage Foundation, a private foundation with $2,000,000 in assets and $150,000 in annual gross receipts, had $15,000 of unrelated business income during the year. Which filing combination is correct?', '["Form 990 for the annual return and Form 990-T for the unrelated business income", "Form 990-PF for the annual return and Form 990-T for the unrelated business income", "Form 990-EZ for the annual return only, since gross receipts are below $200,000", "Form 990-PF only, which includes a section for reporting unrelated business income"]'::jsonb, 1, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of their size, not the standard Form 990 or 990-EZ. Separately, any exempt organization with gross unrelated business income of $1,000 or more must file Form 990-T under Section 6012. Option A incorrectly uses Form 990, which is for public charities, not private foundations.', 'medium', 2),

-- Q8: medium / L3 — NOL deduction for UBIT under Section 512
(3, 'Tax-Exempt Organizations', 'Heritage Arts Council, a 501(c)(3), had an unrelated business net operating loss of $25,000 in 2025 from operating a parking lot. In 2026, it earns $30,000 from the same parking lot and $50,000 in investment dividends. Apply the NOL rules under Section 512 to determine Heritage''s 2026 unrelated business taxable income.', '["$0, because the dividend income offsets the remaining UBI", "$30,000, because NOLs from prior years cannot reduce current UBIT", "$4,000, because the $25,000 NOL carryforward reduces the $30,000 UBI to $5,000, then the $1,000 specific deduction applies", "$5,000, because the specific deduction is unavailable when an NOL carryforward is used"]'::jsonb, 2, 'Under IRC Section 512(b)(6), an NOL deduction is allowed for UBIT purposes, but it is computed using only unrelated business income items. The $25,000 NOL carries forward to reduce the $30,000 parking lot income to $5,000. The $1,000 specific deduction under Section 512(b)(12) then reduces UBTI to $4,000. Dividends are excluded passive income under Section 512(b)(1) and do not enter the UBIT computation. Option D incorrectly claims the specific deduction is unavailable when an NOL is used.', 'medium', 3),

-- Q9: medium / L3 — Personal property rent 10% incidental threshold
(3, 'Tax-Exempt Organizations', 'Pacific Research Institute, a 501(c)(3), leases a building and office furniture to a commercial tenant under a single lease. Annual rent is $200,000, with $185,000 allocated to the building and $15,000 to the furniture. Determine which portion is subject to UBIT under the real and personal property rent rules of Section 512.', '["The entire $200,000 is excluded from UBIT because the $15,000 personal property rent is less than 10% of total rents under the lease", "Only the $185,000 real property portion is excluded; the $15,000 personal property rent is subject to UBIT", "The entire $200,000 is subject to UBIT because the lease includes personal property", "The $185,000 is subject to UBIT but the $15,000 furniture rent is excluded as de minimis"]'::jsonb, 0, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless incidental. Personal property rent is considered incidental when it is less than 10% of total rents under the lease. Here, $15,000 / $200,000 = 7.5%, below the 10% threshold, so the entire $200,000 qualifies for the exclusion. Option B incorrectly splits the rent without considering the 10% incidental threshold.', 'medium', 3),

-- Q10: medium / L3 — Supporting organization requirements under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Gateway Alliance is organized exclusively to raise funds for three public charities in its city and distributes 90% of annual revenue to them. Gateway applies for 501(c)(3) status and claims public charity classification under Section 509(a)(3). What must Gateway demonstrate to qualify as a supporting organization?', '["It must show it is operated, supervised, or controlled by or in connection with one or more public charities and is not controlled by disqualified persons", "It must receive at least one-third of its support from the general public under the public support test", "It must distribute at least 5% of its non-charitable-use assets annually to the supported charities", "It must obtain separate 501(c)(3) determination letters for each supported charity"]'::jsonb, 0, 'Under IRC Section 509(a)(3), a supporting organization must be organized and operated exclusively to support one or more public charities, must meet one of three relationship tests (operated/supervised/controlled by; supervised or controlled in connection with; or operated in connection with), and must not be controlled by disqualified persons. Option B describes the Section 509(a)(1) one-third support test, not the supporting organization rules.', 'medium', 3),

-- Q11: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What is the dissolution clause required in the governing documents of a Section 501(c)(3) organization?', '["A clause requiring the organization to repay all debts before dissolving", "A clause providing that assets will be distributed to another exempt organization or to the government upon dissolution", "A clause requiring a majority vote of members before the organization can dissolve", "A clause prohibiting the organization from dissolving for at least five years after formation"]'::jsonb, 1, 'Under IRC Section 501(c)(3) and Treasury Regulation Section 1.501(c)(3)-1(b)(4), the organizational test requires governing documents to include a dissolution clause directing that remaining assets be distributed to another Section 501(c)(3) organization or to the government. Option A addresses creditor obligations, which is a general corporate law matter, not the specific dissolution clause required for tax-exempt status.', 'easy', 1),

-- Q12: medium / L3 — Bingo exclusion under Section 513(f)
(3, 'Tax-Exempt Organizations', 'Valley Rescue Mission, a 501(c)(3) homeless shelter, hosts weekly bingo nights generating $60,000 annually. Paid employees run the games. The city permits charitable bingo but does not allow commercial bingo operations. Apply the bingo exclusion under Section 513(f) to determine the UBIT treatment.', '["The $60,000 is subject to UBIT because paid employees run the bingo games", "The $60,000 is subject to UBIT because bingo income is never excluded from UBIT for regularly carried on activities", "The $60,000 is excluded from UBIT because bingo is legal in the jurisdiction and commercial bingo is not ordinarily carried on in the area", "The $60,000 is excluded from UBIT only if net proceeds are used exclusively for exempt purposes"]'::jsonb, 2, 'Under IRC Section 513(f), bingo games are excluded from UBIT if the game is legal under state and local law and commercial bingo is not ordinarily carried on in the jurisdiction. The exclusion applies regardless of whether volunteers or paid staff operate the games. Option A incorrectly applies the volunteer labor exclusion test of Section 513(a)(1) rather than the separate bingo exclusion, which does not require volunteer labor.', 'medium', 3),

-- Q13: medium / L2 — Filing deadline and Form 8868 extension
(3, 'Tax-Exempt Organizations', 'Cascade Literacy Foundation, a calendar-year 501(c)(3) public charity, cannot complete its Form 990 by the original due date. Its accountant files Form 8868. By what date must the original Form 990 be filed, and what is the maximum extension available?', '["March 15, with a 3-month automatic extension to June 15", "April 15, with a 6-month automatic extension to October 15", "June 15, with a 3-month automatic extension to September 15", "May 15, with a 6-month automatic extension to November 15"]'::jsonb, 3, 'Under IRC Section 6072(e), tax-exempt organizations must file Form 990 by the 15th day of the 5th month after the end of the tax year. For calendar-year organizations, this is May 15. Form 8868 provides an automatic 6-month extension to November 15. Option A applies the due date for S corporations (March 15), not exempt organizations.', 'medium', 2),

-- Q14: hard / L3 — Intermediate sanctions computation under Section 4958
(3, 'Tax-Exempt Organizations', 'Metro Cultural Center, a 501(c)(3), pays its chief development officer total compensation of $475,000. Comparable compensation is $275,000, making the excess benefit $200,000. The board chair approved the compensation without reviewing comparability data and knew the amount was above market. The officer does not repay within the correction period. Compute the total excise taxes under Section 4958.', '["$50,000 on the officer (25%) plus $20,000 on the board chair (10%), totaling $70,000", "$450,000 on the officer ($50,000 initial at 25% plus $400,000 additional at 200%) and $20,000 on the board chair (10% capped at $20,000), totaling $470,000", "$200,000 on the officer (100%) and $10,000 on the board chair (5%), totaling $210,000", "$400,000 on the officer (200%) only, with no tax on the board chair because the organization is not a private foundation"]'::jsonb, 1, 'Under IRC Section 4958, the initial tax on the disqualified person is 25% of the excess benefit ($200,000 x 25% = $50,000). If not corrected, an additional 200% tax applies ($200,000 x 200% = $400,000). The organization manager who knowingly participates is taxed at 10%, capped at $20,000 per transaction ($200,000 x 10% = $20,000). Total: $50,000 + $400,000 + $20,000 = $470,000. Option A omits the additional 200% tax for failure to correct.', 'hard', 3),

-- Q15: medium / L3 — Research exclusion from UBIT under Section 512(b)(7)-(9)
(3, 'Tax-Exempt Organizations', 'Northern State University, a 501(c)(3), operates a genetics lab with two projects. Project Alpha is funded by a federal NIH grant with results published in peer-reviewed journals. Project Beta is funded by a pharmaceutical company under a contract giving exclusive rights to all findings. Apply the research exclusion to determine UBIT treatment.', '["Both projects are excluded because all research at a university is automatically exempt from UBIT", "Neither project is excluded because the lab generates income from selling research services", "Project Alpha is excluded because it is government-funded research with publicly available results, but Project Beta income is subject to UBIT because results are not publicly available", "Project Beta is excluded because it is performed by a university, but Project Alpha is subject to UBIT as government-funded work"]'::jsonb, 2, 'Under IRC Sections 512(b)(7)-(9), research performed for the U.S. government or by a college/university is excluded from UBIT if results are freely available to the public. Project Alpha meets both conditions. Project Beta''s exclusive licensing means results are not publicly available, removing the public availability prong. Option A overstates the university research exclusion, which does not apply when results are restricted to a private sponsor.', 'medium', 3),

-- Q16: hard / L4 — Section 4945 taxable expenditures multi-grant analysis
(3, 'Tax-Exempt Organizations', 'Meridian Foundation, a private foundation, makes three grants: (1) $100,000 to a 501(c)(3) food bank, (2) $75,000 to a 501(c)(4) social welfare organization for voter education without exercising expenditure responsibility, and (3) $50,000 to an individual researcher without prior IRS approval of the grant procedure. Evaluate each grant under Section 4945 and determine the total taxable expenditure amount.', '["$50,000, because only the individual grant is a taxable expenditure", "$75,000, because only the grant to the 501(c)(4) without expenditure responsibility qualifies", "$100,000, because grants to all external organizations are taxable expenditures", "$125,000, because both the 501(c)(4) grant without expenditure responsibility ($75,000) and the unapproved individual grant ($50,000) are taxable expenditures"]'::jsonb, 3, 'Under IRC Section 4945(d), taxable expenditures include grants to organizations other than 501(c)(3) public charities unless the foundation exercises expenditure responsibility, and grants to individuals unless the grant procedure is pre-approved by the IRS. The $100,000 to the 501(c)(3) is not a taxable expenditure. The $75,000 to the 501(c)(4) without expenditure responsibility and the $50,000 unapproved individual grant total $125,000. Option A ignores that grants to non-501(c)(3) entities require expenditure responsibility.', 'hard', 4),

-- Q17: easy / L1 — Automatic public charity categories
(3, 'Tax-Exempt Organizations', 'Which organizations are automatically classified as public charities regardless of their funding sources?', '["Churches, schools, and hospitals", "Private operating foundations and supporting organizations", "Organizations with gross receipts exceeding $500,000", "Organizations that have been tax-exempt for more than five years"]'::jsonb, 0, 'Under IRC Section 509(a)(1) referencing Section 170(b)(1)(A), churches, schools, hospitals, and certain other organizations are automatically classified as public charities without needing to satisfy the one-third public support test. Option B incorrectly classifies private operating foundations as public charities; they remain private foundations with different operational rules.', 'easy', 1),

-- Q18: medium / L2 — Penalty for failure to file Form 990
(3, 'Tax-Exempt Organizations', 'Willow Park Youth Services, a 501(c)(3) with $800,000 in gross receipts, files its Form 990 seventy-five days late without reasonable cause. What penalty does the IRS impose under Section 6652(c)?', '["$100 per day up to a maximum of $53,000", "$20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts", "A flat penalty of $10,000 with no per-day component", "No penalty because the organization is tax-exempt and exempt from all filing penalties"]'::jsonb, 1, 'Under IRC Section 6652(c)(1)(A), organizations with gross receipts under $1,186,000 face a penalty of $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts. At $800,000 gross receipts, the cap is $10,500 (since 5% x $800,000 = $40,000 exceeds $10,500). Option A applies the penalty rate for larger organizations with gross receipts of $1,186,000 or more.', 'medium', 2),

-- Q19: hard / L4 — Sections 4940 and 4942 combined compliance evaluation
(3, 'Tax-Exempt Organizations', 'Goldcrest Foundation, a private foundation, has $8,000,000 in non-charitable-use assets and $300,000 in net investment income for 2026. It distributes $350,000 to charitable organizations and pays $4,170 in Section 4940 excise tax. The treasurer asserts the foundation met the 5% minimum distribution because $350,000 exceeds 4% of assets. Evaluate compliance with both Sections 4940 and 4942.', '["The foundation is fully compliant because $350,000 exceeds the $300,000 net investment income", "The foundation owes additional Section 4940 tax because the 1.39% rate applies only to the first $200,000 of net investment income", "The foundation satisfied Section 4940 but failed Section 4942 because the distributable amount includes the excise tax paid on net investment income", "The foundation failed Section 4942 because the required distribution is $400,000 (5% x $8,000,000), creating a $50,000 shortfall subject to a 30% initial excise tax"]'::jsonb, 3, 'Under IRC Section 4942, a private foundation must distribute at least 5% of the fair market value of its non-charitable-use assets annually. Here, 5% x $8,000,000 = $400,000 required. The $350,000 distribution leaves a $50,000 underdistribution subject to a 30% initial excise tax ($15,000). The Section 4940 tax of $4,170 (1.39% x $300,000) is correctly calculated. Option A confuses net investment income with the asset-based distribution requirement.', 'hard', 4),

-- Q20: easy / L1 — Private foundation presumption under Section 509
(3, 'Tax-Exempt Organizations', 'Under Section 509, what is the default classification for a 501(c)(3) organization?', '["Public charity until proven otherwise by the IRS", "Supporting organization under Section 509(a)(3)", "Private foundation unless it demonstrates public charity status", "Tax-exempt social welfare organization under Section 501(c)(4)"]'::jsonb, 2, 'Under IRC Section 509(a), all Section 501(c)(3) organizations are presumed to be private foundations unless they demonstrate they qualify as public charities under one of the exceptions in Sections 509(a)(1) through 509(a)(4). Option A reverses the presumption; the burden is on the organization to prove public charity status, not on the IRS to disprove it.', 'easy', 1),

-- Q21: easy / L1 — Form 990-N e-Postcard threshold
(3, 'Tax-Exempt Organizations', 'What annual information return must a small 501(c)(3) organization with gross receipts of $40,000 file with the IRS?', '["Form 990 with all required schedules", "Form 990-EZ as a simplified return", "No return is required for organizations with gross receipts below $50,000", "Form 990-N (e-Postcard), an electronic notice confirming continued eligibility"]'::jsonb, 3, 'Under IRC Section 6033(i), tax-exempt organizations with gross receipts normally $50,000 or less may file the Form 990-N electronic postcard, which requires only the organization''s name, address, EIN, and confirmation of continued eligibility. Option C incorrectly states no filing is required; failure to file any return for three consecutive years results in automatic revocation of exempt status.', 'easy', 1),

-- Q22: medium / L2 — Section 4941 tax on foundation manager
(3, 'Tax-Exempt Organizations', 'Bradley Hart, legal counsel and board member of the Hart Family Foundation, approves a $200,000 lease of foundation property to the founder''s son, knowing the transaction constitutes self-dealing under Section 4941. The lease is at fair market value. What excise tax is imposed on Bradley Hart as a foundation manager?', '["5% of the amount involved, which is $10,000", "10% of the amount involved, which is $20,000", "25% of the excess benefit, which is $50,000", "No tax because the lease is at fair market value"]'::jsonb, 0, 'Under IRC Section 4941(a)(2), a foundation manager who knowingly participates in an act of self-dealing is subject to a 5% excise tax on the amount involved per taxable period. Here, 5% x $200,000 = $10,000. Option B applies the 10% rate, which is the initial tax on the self-dealer (the disqualified person), not the foundation manager. Fair market value is irrelevant because self-dealing is based on the nature of the transaction.', 'medium', 2),

-- Q23: medium / L2 — Donated goods exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Second Chance Resale, a 501(c)(3) job training program, operates a retail store selling donated clothing and newly purchased accessories. In 2026, donated clothing sales generate $180,000 and new accessory sales generate $45,000. Which portion qualifies for the donated goods UBIT exclusion under Section 513(a)(3)?', '["The entire $225,000 because the store supports an exempt purpose", "The $180,000 from donated clothing sales qualifies because substantially all of those items were received as gifts", "Neither portion qualifies because the store also sells purchased goods alongside donated merchandise", "The $45,000 from accessories qualifies because the markup on donated goods is too high to be excluded"]'::jsonb, 1, 'Under IRC Section 513(a)(3), income from selling donated merchandise is excluded from UBIT when substantially all of the items sold were received as gifts or contributions. The $180,000 in donated clothing sales qualifies. The $45,000 from newly purchased accessories does not because those items were not donated. Option C incorrectly applies an all-or-nothing approach; the exclusion applies to the donated goods activity separately.', 'medium', 2),

-- Q24: medium / L2 — Section 509(a)(2) gross receipts test for public charity
(3, 'Tax-Exempt Organizations', 'Summit Nature Center, a 501(c)(3), receives $300,000 in membership fees, $200,000 from guided nature tours related to its educational mission, and $150,000 from government grants. Investment income totals $50,000. Under which provision is Summit most likely to qualify as a public charity?', '["Section 509(a)(1), because it receives substantial government support", "Section 509(a)(3), because it operates in connection with other public charities", "Section 509(a)(2), because it receives more than one-third of support from contributions, membership fees, and gross receipts from related activities", "Section 509(a)(4), because it conducts public safety testing"]'::jsonb, 2, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if it normally receives more than one-third of its support from contributions, membership fees, and gross receipts from activities related to exempt functions. Summit''s qualifying receipts total $650,000 ($300,000 + $200,000 + $150,000) out of $700,000, well exceeding one-third. Option A describes the Section 509(a)(1) test, which focuses on government and public contributions but not gross receipts from related activities.', 'medium', 2),

-- Q25: medium / L2 — Schedule J compensation disclosure on Form 990
(3, 'Tax-Exempt Organizations', 'Beacon Health Alliance, a 501(c)(3) hospital network, files Form 990 annually. The IRS requires detailed compensation disclosure for officers, directors, and key employees. Which Form 990 schedule reports this information?', '["Schedule A, which reports public charity status and public support calculations", "Schedule B, which reports the schedule of contributors", "Schedule D, which reports supplemental financial statements", "Schedule J, which reports compensation information for officers, directors, and key employees"]'::jsonb, 3, 'Under IRS Form 990 instructions, Schedule J (Compensation Information) requires detailed reporting of compensation for officers, directors, trustees, key employees, and highest-compensated employees. Option A (Schedule A) reports public charity status and public support data, not individual compensation information for organization leadership.', 'medium', 2),

-- Q26: easy / L1 — Private inurement prohibition definition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Net earnings of the organization from benefiting any private shareholder or individual who is an insider", "The organization from earning any revenue from commercial activities", "Board members from serving on the boards of other nonprofit organizations", "The organization from accumulating reserves exceeding one year of operating expenses"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private inurement prohibition bars any part of the net earnings of a tax-exempt organization from inuring to the benefit of any private shareholder or individual, meaning insiders such as founders, officers, directors, and those with substantial influence. Option B confuses private inurement with UBIT rules; earning commercial revenue is permitted but may be subject to tax.', 'easy', 1),

-- Q27: easy / L1 — Section 4940 excise tax rate on net investment income
(3, 'Tax-Exempt Organizations', 'What is the excise tax rate on the net investment income of a private foundation under Section 4940?', '["2%, reduced to 1% if certain distribution requirements are met", "1.39% of net investment income", "5% of net investment income", "10% of net investment income"]'::jsonb, 1, 'Under IRC Section 4940(a), private foundations are subject to a 1.39% excise tax on net investment income, which includes interest, dividends, rents, royalties, and net capital gains. Option A describes the pre-2020 dual-rate structure that was replaced by the flat 1.39% rate under the Taxpayer Certainty and Disaster Tax Relief Act of 2019.', 'easy', 1),

-- Q28: easy / L1 — Section 4945 excise tax rate on taxable expenditures
(3, 'Tax-Exempt Organizations', 'What is the initial excise tax rate imposed on taxable expenditures by a private foundation under Section 4945?', '["5% of the taxable expenditure", "10% of the taxable expenditure", "20% of the taxable expenditure", "30% of the taxable expenditure"]'::jsonb, 2, 'Under IRC Section 4945(a)(1), the initial excise tax on taxable expenditures made by a private foundation is 20% of each taxable expenditure. Taxable expenditures include lobbying, political activity, grants to individuals without IRS-approved procedures, and grants to non-charities without expenditure responsibility. Option B (10%) is the initial self-dealing tax rate on the self-dealer under Section 4941, not the taxable expenditure rate.', 'easy', 1),

-- Q29: easy / L1 — Disqualified persons under Section 4958 intermediate sanctions
(3, 'Tax-Exempt Organizations', 'Under Section 4958, which individuals are classified as disqualified persons subject to intermediate sanctions?', '["All employees of the organization regardless of their position or influence", "Only the organization''s external auditors and legal counsel", "Only donors who contribute more than $5,000 annually to the organization", "Officers, directors, and persons with substantial influence over the organization"]'::jsonb, 3, 'Under IRC Section 4958(f)(1), disqualified persons include any person who was in a position to exercise substantial influence over the affairs of the organization at any time during a five-year lookback period. This includes officers, directors, trustees, key employees, and their family members. Option A overstates the definition; rank-and-file employees without substantial influence are not disqualified persons.', 'easy', 1),

-- Q30: medium / L3 — "Regularly carried on" test application in UBIT three-part test
(3, 'Tax-Exempt Organizations', 'Hilltop Animal Rescue, a 501(c)(3), operates a two-week holiday craft fair each December, generating $45,000 from selling ornaments and gifts produced by volunteers. A commercial craft store across the street operates year-round. Apply the "regularly carried on" element of the UBIT three-part test to determine whether the craft fair income is subject to UBIT.', '["The income is not subject to UBIT because a two-week seasonal activity is not conducted with frequency and continuity comparable to year-round commercial operations", "The income is subject to UBIT because it directly competes with the commercial craft store", "The income is subject to UBIT because $45,000 exceeds the $1,000 specific deduction threshold", "The income is excluded from UBIT under the same statutory exclusion that applies to bingo games"]'::jsonb, 0, 'Under IRC Section 513 and Treasury Regulation Section 1.513-1(c)(2), an activity is "regularly carried on" only if conducted with frequency and continuity comparable to similar commercial activities. A two-week annual event does not meet this standard compared to year-round operations. Since the second prong of the three-part test fails, the income is not UBIT. Option B confuses competition with the regulatory standard; competition alone does not establish that an activity is regularly carried on.', 'medium', 3)
;

COMMIT;
